// ========================================
// 🔄 Excel Row Consolidator
// ========================================
// Risolve il problema: prezzi su righe successive
// Consolida righe correlate in singoli item completi
//
// LOGICA:
// 1. Se riga ha DESCRIZIONE ma manca COSTO_MATERIALE
// 2. E la riga successiva ha COSTO_MATERIALE
// 3. → Merge i dati mantenendo descrizione da riga 1 e prezzo da riga 2
// ========================================

const rows = $input.all();
const consolidated = [];
let currentCategory = '';
let i = 0;

while (i < rows.length) {
  const current = rows[i].json;
  const next = i + 1 < rows.length ? rows[i + 1].json : null;

  const hasDescription = current['DESCRIZIONE  COMPLETA                                   '] && 
                         current['DESCRIZIONE  COMPLETA                                   '].trim().length > 0;
  const hasCost = current['COSTO UNITAR. MATERIALE'] && 
                  current['COSTO UNITAR. MATERIALE'] !== '' && 
                  current['COSTO UNITAR. MATERIALE'] !== null;
  const hasUM = current['U.M.'] && current['U.M.'].trim() !== '';

  // Identifica se è una riga categoria (MACRO valorizzato, no U.M., no costo)
  const isCategory = current['MACRO'] && current['MACRO'].trim() !== '' && !hasUM && !hasCost;

  if (isCategory) {
    // Aggiorna categoria corrente e skip questa riga
    currentCategory = current['MACRO'].trim();
    i++;
    continue;
  }

  // Caso 1: Riga completa (ha descrizione, UM e costo)
  if (hasDescription && hasUM && hasCost) {
    consolidated.push({
      json: {
        ...current,
        'MACRO': current['MACRO'] || currentCategory,
        __rowNumber: i + 1,
        __consolidatedFrom: 'single_row'
      }
    });
    i++;
  }
  // Caso 2: Riga incompleta + riga successiva con dati
  else if (hasDescription && hasUM && !hasCost && next) {
    const nextHasCost = next['COSTO UNITAR. MATERIALE'] && 
                        next['COSTO UNITAR. MATERIALE'] !== '' && 
                        next['COSTO UNITAR. MATERIALE'] !== null;
    const nextHasTime = next['Tempo pos min/copp'] && 
                        next['Tempo pos min/copp'] !== '' && 
                        next['Tempo pos min/copp'] !== null;

    if (nextHasCost || nextHasTime) {
      // Merge righe
      consolidated.push({
        json: {
          'MACRO': current['MACRO'] || currentCategory,
          'DESCRIZIONE  COMPLETA                                   ': current['DESCRIZIONE  COMPLETA                                   '],
          'U.M.': current['U.M.'],
          "Q.TA'": current["Q.TA'"] || next["Q.TA'"] || '',
          'COSTO UNITAR. MATERIALE': nextHasCost ? next['COSTO UNITAR. MATERIALE'] : current['COSTO UNITAR. MATERIALE'],
          'Tempo pos min/copp': nextHasTime ? next['Tempo pos min/copp'] : current['Tempo pos min/copp'],
          'Preventivo': current['Preventivo'] || '',
          __rowNumber: i + 1,
          __consolidatedFrom: 'merged_with_row_' + (i + 2),
          __mergedRows: [i + 1, i + 2]
        }
      });
      i += 2; // Skip both rows
    } else {
      // Riga incompleta senza match successivo - passa comunque (AI deciderà)
      consolidated.push({
        json: {
          ...current,
          'MACRO': current['MACRO'] || currentCategory,
          __rowNumber: i + 1,
          __consolidatedFrom: 'incomplete_row'
        }
      });
      i++;
    }
  }
  // Caso 3: Riga con solo descrizione, senza UM (probabilmente categoria o nota)
  else if (hasDescription && !hasUM) {
    // Probabile categoria o riga da skippare
    i++;
    continue;
  }
  // Caso 4: Altre righe incomplete
  else {
    i++;
    continue;
  }
}

return consolidated;
